/*
 * A059390  Numbers that are not the sum of two nonzero Fibonacci numbers.
 * https://oeis.org/A059390
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = numbers that are NOT the sum of two non‑zero Fibonacci
 *            numbers
 * Range:     u8 n <= 192, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by testing successive integers and storing those that
 * cannot be written as F_i + F_j (with F_i, F_j > 0).  A cache is maintained so
 * that calls with arbitrary n are answered in O(1).  This implementation is
 * valid C11 and C++17; no special case for the first few terms. */

#include <stdlib.h>
#include <stdbool.h>

/* --------------------------------------------------------------------- */
/*  Fibonacci data                                                  */
/* --------------------------------------------------------------------- */
static seq_t fibs[200];      /* Fibonacci numbers (1, 2, 3, 5, ... )   */
static size_t fib_count   = 0;   /* number of computed Fibonacci numbers   */
static seq_t fib_max       = 0;   /* largest Fibonacci number known         */

/* --------------------------------------------------------------------- */
/*  Cache of the sequence a(1)…a(k)                                 */
/* --------------------------------------------------------------------- */
static seq_t *cache      = NULL;  /* allocated cache                       */
static size_t cache_len  = 0;     /* number of filled cache entries         */
static size_t cache_cap  = 0;     /* current capacity of the cache          */

/* --------------------------------------------------------------------- */
/*  Binary search – is x a Fibonacci number?                          */
/* --------------------------------------------------------------------- */
static bool is_fib(seq_t x)
{
    size_t low = 0, high = fib_count;
    while (low < high) {
        size_t mid = low + (high - low) / 2;
        if (fibs[mid] == x) return true;
        if (fibs[mid] < x)
            low = mid + 1;
        else
            high = mid;
    }
    return false;
}

/* --------------------------------------------------------------------- */
/*  Ensure that Fibonacci numbers are known up to at least 'limit'.   */
/* --------------------------------------------------------------------- */
static void ensure_fibs_up_to(seq_t limit)
{
    while (fib_max < limit) {
        if (fib_count < 2) {
            fibs[0] = (seq_t)1;
            fibs[1] = (seq_t)2;
            fib_count = 2;
            fib_max   = fibs[1];
            if (fib_max >= limit) break;
            continue;
        }

        seq_t next = fibs[fib_count - 1] + fibs[fib_count - 2];
        /* Detect unsigned overflow (C++/C both wrap). */
        if (next <= fibs[fib_count - 1])
            break;
        fibs[fib_count++] = next;
        fib_max = next;
    }
}

/* --------------------------------------------------------------------- */
/*  Grow the sequence cache and append a value.                          */
/* --------------------------------------------------------------------- */
static void append_cache(seq_t val)
{
    if (cache_len == cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 64;
        void *p = realloc(cache, new_cap * sizeof(seq_t));
        cache = (seq_t *)p;            /* explicit cast for C++ */
        cache_cap = new_cap;
    }
    cache[cache_len++] = val;
}

/* --------------------------------------------------------------------- */
/*  Main sequence function.                                              */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    static seq_t tested_up_to = 0;   /* highest integer previously tested */
    seq_t next_test = tested_up_to + 1;

    while (cache_len < (size_t)n) {
        if (next_test <= tested_up_to)
            next_test = tested_up_to + 1;
        tested_up_to = next_test;

        ensure_fibs_up_to(next_test);

        bool sum_of_two = false;
        for (size_t i = 0; i < fib_count && fibs[i] <= next_test - 1; ++i) {
            seq_t rem = next_test - fibs[i];
            if (is_fib(rem)) {
                sum_of_two = true;
                break;
            }
        }

        if (!sum_of_two)
            append_cache(next_test);

        ++next_test;
    }

    return cache[n - 1];
}
